package com.xulihang.psd;

import java.awt.AlphaComposite;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * A Photoshop document built in memory.
 * <p>
 * The generated file is an 8-bit RGB PSD containing flat layers (no groups):
 * raster layers added with {@link #addImageLayer} and editable text layers
 * added with {@link #addTextLayer}. Layers are ordered bottom-to-top: the first
 * layer added is the bottom layer.
 *
 * <pre>{@code
 * Psd psd = new Psd(800, 600);
 * psd.addImageLayer("Background", backgroundImage, 0, 0);
 * psd.addTextLayer(new TextLayer("Hello PSD", 100, 200)
 *         .setFontFamily("Arial")
 *         .setFontSize(48)
 *         .setColor(Color.BLACK));
 * psd.write(Paths.get("output.psd"));
 * }</pre>
 */
public final class Psd {
    private final int width;
    private final int height;
    private final List<Layer> layers = new ArrayList<>();
    private BufferedImage composite;

    public Psd(int width, int height) {
        if (width <= 0 || height <= 0) {
            throw new IllegalArgumentException("Document size must be positive");
        }
        if (width > 30000 || height > 30000) {
            throw new IllegalArgumentException("PSD documents are limited to 30000x30000 pixels");
        }
        this.width = width;
        this.height = height;
    }

    public int getWidth() {
        return width;
    }

    public int getHeight() {
        return height;
    }

    public List<Layer> getLayers() {
        return Collections.unmodifiableList(layers);
    }

    public Psd addLayer(Layer layer) {
        if (layer == null) {
            throw new IllegalArgumentException("Layer must not be null");
        }
        layers.add(layer);
        return this;
    }

    public ImageLayer addImageLayer(String name, BufferedImage image, int left, int top) {
        ImageLayer layer = new ImageLayer(name, image, left, top);
        addLayer(layer);
        return layer;
    }

    public ImageLayer addImageLayer(BufferedImage image) {
        return addImageLayer("Layer", image, 0, 0);
    }

    public TextLayer addTextLayer(TextLayer layer) {
        addLayer(layer);
        return layer;
    }

    /**
     * Provides the flattened composite image stored in the PSD. When not set,
     * the composite is generated by drawing all visible layers in order.
     * The image must have the same size as the document.
     */
    public Psd setComposite(BufferedImage composite) {
        this.composite = composite;
        return this;
    }

    public BufferedImage getCompositeImage() {
        if (composite != null) {
            return composite;
        }

        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        for (Layer layer : layers) {
            if (!layer.isVisible()) {
                continue;
            }
            BufferedImage layerImage = layer.getImage();
            if (layerImage == null) {
                continue;
            }
            graphics.setComposite(AlphaComposite.getInstance(
                    AlphaComposite.SRC_OVER, layer.getOpacity() / 255f));
            graphics.drawImage(layerImage, layer.getLeft(), layer.getTop(), null);
        }
        graphics.dispose();
        return image;
    }

    /** Writes the document as an 8-bit RGB PSD to a byte array. */
    public byte[] toByteArray() {
        return PsdWriter.write(this);
    }

    public void write(Path path) throws IOException {
        Files.write(path, toByteArray());
    }

    public void write(File file) throws IOException {
        write(file.toPath());
    }

    public void write(OutputStream output) throws IOException {
        output.write(toByteArray());
        output.flush();
    }
}
